import{_ as l}from"./chunks/设计思路.qSOt4CAf.js";import{c as o,Q as a,j as s,m as e}from"./chunks/framework.CHJbb1iY.js";const r="/my-knowledge/assets/%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E6%B5%81%E7%A8%8B.JcharXTd.png",i="/my-knowledge/assets/%E9%9C%80%E6%B1%82%E5%88%86%E6%9E%90.ovlm4Xt2.png",n="/my-knowledge/assets/%E7%99%BB%E5%BD%95%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.CieMxKV0.png",g="/my-knowledge/assets/%E6%8B%89%E5%8F%96%E5%9C%A8%E7%BA%BF%E7%94%A8%E6%88%B7%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.I6bkM5oe.png",d="/my-knowledge/assets/%E7%A7%81%E8%81%8A%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.5BD-34zd.png",p="/my-knowledge/assets/%E7%BE%A4%E8%81%8A%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.Bwr53wIT.png",c="/my-knowledge/assets/%E5%8F%91%E6%96%87%E4%BB%B6%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.CI4ApcTu.png",h="/my-knowledge/assets/%E4%BF%A1%E6%81%AF%E6%8E%A8%E9%80%81%E5%8A%9F%E8%83%BD%E7%95%8C%E9%9D%A2%E6%BC%94%E7%A4%BA.BULbAZwH.png",k=JSON.parse('{"title":"","description":"","frontmatter":{"aside":"right","outline":[2,3]},"headers":[],"relativePath":"docs/Java/第三阶段/项目/多用户即时通讯系统/1. 项目介绍.md","filePath":"docs/Java/第三阶段/项目/多用户即时通讯系统/1. 项目介绍.md"}'),_={name:"docs/Java/第三阶段/项目/多用户即时通讯系统/1. 项目介绍.md"};function E(m,t,u,A,b,B){return a(),s("div",null,[...t[0]||(t[0]=[e('<h1 style="text-align:center;font-weight:bold;">项目介绍</h1><hr><h2 id="_1-项目开发流程介绍" tabindex="-1">1. 项目开发流程介绍 <a class="header-anchor" href="#_1-项目开发流程介绍" aria-label="Permalink to &quot;1. 项目开发流程介绍&quot;">​</a></h2><p><img src="'+r+'" alt="alt text"></p><h3 id="_1-组成部分" tabindex="-1">（1）组成部分 <a class="header-anchor" href="#_1-组成部分" aria-label="Permalink to &quot;（1）组成部分&quot;">​</a></h3><ul><li>需求分析师</li><li>架构师 / 项目经理</li><li>开发 <ul><li>前端</li><li>后端</li></ul></li><li>测试</li><li>运维（实施工程师）</li></ul><h3 id="_2-补充内容" tabindex="-1">（2）补充内容 <a class="header-anchor" href="#_2-补充内容" aria-label="Permalink to &quot;（2）补充内容&quot;">​</a></h3><ul><li>项目的级别越大，需求分析和项目设计所要的时间就越长，分到的薪水也相对较高，后三者开发薪水占比相对来说会比测试和运维高，如果项目较小，开发占比时间会多一些</li><li>实际开发中一般是<strong>边开发边设计</strong></li><li>程序员开发完成后<strong>需要自测</strong>，最后才集中到测试阶段</li></ul><h2 id="_2-项目介绍" tabindex="-1">2. 项目介绍 <a class="header-anchor" href="#_2-项目介绍" aria-label="Permalink to &quot;2. 项目介绍&quot;">​</a></h2><h3 id="_1-需求分析" tabindex="-1">（1）需求分析 <a class="header-anchor" href="#_1-需求分析" aria-label="Permalink to &quot;（1）需求分析&quot;">​</a></h3><p><img src="'+i+'" alt="alt text"></p><h3 id="_2-界面演示" tabindex="-1">（2）界面演示 <a class="header-anchor" href="#_2-界面演示" aria-label="Permalink to &quot;（2）界面演示&quot;">​</a></h3><p><img src="'+n+'" alt="alt text"></p><p><img src="'+g+'" alt="alt text"></p><h4 id="补充功能-无异常退出" tabindex="-1"><span style="font-weigh:bold;font-size:30px;">补充功能：无异常退出</span> <a class="header-anchor" href="#补充功能-无异常退出" aria-label="Permalink to &quot;&lt;span style = &quot;font-weigh:bold;font-size:30px&quot;&gt;补充功能：无异常退出&lt;/span&gt;&quot;">​</a></h4><p><img src="'+d+'" alt="alt text"></p><p><img src="'+p+'" alt="alt text"></p><p><img src="'+c+'" alt="alt text"></p><p><img src="'+h+'" alt="alt text"></p><h3 id="_3-设计思路-非常重要" tabindex="-1">（3）设计思路（<span style="color:red;font-weight:bold;">非常重要！！！</span>） <a class="header-anchor" href="#_3-设计思路-非常重要" aria-label="Permalink to &quot;（3）设计思路（&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;非常重要！！！&lt;/span&gt;）&quot;">​</a></h3><p><img src="'+l+'" alt="alt text"></p><h4 id="分析" tabindex="-1">分析 <a class="header-anchor" href="#分析" aria-label="Permalink to &quot;分析&quot;">​</a></h4><ul><li><strong>整体思路</strong><ul><li><strong>通讯过程中涉及用户的概念，不能再单一的发送信息，需要<span style="color:red;font-weight:bold;">使用对象的思想封装信息</span>，使用<span style="color:red;font-weight:bold;">对象流</span>完成信息的读取和输出</strong></li><li><strong>因为是多用户通信系统，为了不影响各自的通信，实现独立，需要使用</strong><span style="color:red;font-weight:bold;">线程</span></li><li><strong>用户进行网络通信，需要使用 socket，不同的用户会和服务器产生</strong><span style="color:red;font-weight:bold;">多对 socket</span>，这里<span style="color:red;font-weight:bold;">使用集合管理</span>，<strong>群发功能</strong>就可以以此为基础实现（<strong>服务端</strong>）</li></ul></li><li><strong>客户端</strong><blockquote><p>考虑到信息的交互类型可能不同，可以有文本，文件等，这里可以<strong>启动不同的线程负责不同的模块</strong>，这里可以使用<strong>集合管理线程</strong></p></blockquote></li><li><strong>服务端</strong><blockquote><p>对<strong>于一个客户端对象，可以和多个用户进行通信</strong>，在服务端当然需要多个线程，这里可以使用<strong>集合管理线程</strong></p></blockquote></li><li><strong>两个对象</strong><ul><li><strong>message</strong></li><li><strong>user</strong>：通过给服务端发送请求，判断是否是合法用户</li></ul></li></ul><h3 id="_4-项目相关技术" tabindex="-1">（4）项目相关技术 <a class="header-anchor" href="#_4-项目相关技术" aria-label="Permalink to &quot;（4）项目相关技术&quot;">​</a></h3><ul><li><ol><li>Java 面向对象编程</li></ol></li><li><ol start="2"><li>网络编程</li></ol></li><li><ol start="3"><li>多线程</li></ol></li><li><ol start="4"><li>IO 流</li></ol></li><li><ol start="5"><li>Mysql（数据库还未学习，这里<strong>使用集合充当内存数据库</strong>）</li></ol></li></ul>',25)])])}const x=o(_,[["render",E]]);export{k as __pageData,x as default};
